#include "core.h"
#include <stdio.h>
#include <string.h>
namespace Ota {
Json Json::integer(int64_t n){Json j;j.type=Integer;j.number=n;return j;}Json Json::obj(){Json j;j.type=Object;return j;}Json Json::list(){Json j;j.type=Array;return j;}
const Json &Json::get(const std::string &k)const{static const Json empty;std::map<std::string,Json>::const_iterator i=object.find(k);return i==object.end()?empty:i->second;}
std::string Json::text(const std::string &k)const{return get(k).type==String?get(k).string:std::string();}int64_t Json::num(const std::string &k)const{return get(k).type==Integer?get(k).number:-1;}
bool Json::has(const std::string &k)const{return object.find(k)!=object.end();}
bool Json::keys(const char *names)const{if(type!=Object)return false;size_t n=0;std::string s(names);size_t p=0,q;do{q=s.find(',',p);if(!has(s.substr(p,q==std::string::npos?q:q-p)))return false;n++;p=q+1;}while(q!=std::string::npos);return object.size()==n;}
std::string decimal(int64_t n){char b[32];snprintf(b,sizeof b,"%lld",(long long)n);return b;}
bool hex(const std::string &s,size_t n){return s.size()==n&&s.find_first_not_of("0123456789abcdef")==std::string::npos;}
bool identifier(const std::string &s){return !s.empty()&&s.size()<=96&&s.find_first_not_of("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-")==std::string::npos&&s!="."&&s!="..";}
static void utf8(std::string &s,unsigned c){if(c<128)s+=char(c);else if(c<2048){s+=char(192|(c>>6));s+=char(128|(c&63));}else if(c<65536){s+=char(224|(c>>12));s+=char(128|((c>>6)&63));s+=char(128|(c&63));}else{s+=char(240|(c>>18));s+=char(128|((c>>12)&63));s+=char(128|((c>>6)&63));s+=char(128|(c&63));}}
class Parser {
 const std::string &s;size_t p;unsigned nodes;
 void ws(){while(p<s.size()&&(s[p]==' '||s[p]=='\r'||s[p]=='\n'||s[p]=='\t'))p++;}
 bool u4(unsigned &c){c=0;for(int i=0;i<4;i++){if(p==s.size())return false;char x=s[p++];const char*h=strchr("0123456789abcdef",x>='A'&&x<='F'?x+32:x);if(!h||!x)return false;c=c*16+(h-"0123456789abcdef");}return true;}
 bool str(std::string &out){if(p==s.size()||s[p++]!='"')return false;out.clear();while(p<s.size()){unsigned char c=s[p++];if(c=='"')return true;if(c<32)return false;if(c=='\\'){if(p==s.size())return false;char e=s[p++];if(e=='"'||e=='\\'||e=='/')out+=e;else if(e=='b')out+='\b';else if(e=='f')out+='\f';else if(e=='n')out+='\n';else if(e=='r')out+='\r';else if(e=='t')out+='\t';else if(e=='u'){unsigned u,v;if(!u4(u))return false;if(u>=0xd800&&u<=0xdbff){if(s.substr(p,2)!="\\u")return false;p+=2;if(!u4(v)||v<0xdc00||v>0xdfff)return false;u=0x10000+((u-0xd800)<<10)+(v-0xdc00);}else if(u>=0xdc00&&u<=0xdfff)return false;utf8(out,u);}else return false;}else if(c<128)out+=char(c);else{unsigned len=c>=0xc2&&c<=0xdf?1:c>=0xe0&&c<=0xef?2:c>=0xf0&&c<=0xf4?3:0;if(!len||p+len>s.size())return false;unsigned u=c&((1<<(6-len))-1);for(unsigned i=0;i<len;i++){unsigned char d=s[p++];if((d&192)!=128)return false;u=(u<<6)|(d&63);}if(u<(len==1?128:len==2?2048:65536)||u>0x10ffff||(u>=0xd800&&u<=0xdfff))return false;utf8(out,u);}}return false;}
 bool value(Json &j,unsigned depth){if(depth>8||++nodes>12000)return false;ws();if(p==s.size())return false;char c=s[p];if(c=='"'){j.type=Json::String;return str(j.string);}if(c=='{'||c=='['){bool obj=c=='{';p++;j.type=obj?Json::Object:Json::Array;ws();if(p<s.size()&&s[p]==(obj?'}':']')){p++;return true;}do{ws();std::string key;if(obj){if(!str(key)||j.has(key))return false;ws();if(p==s.size()||s[p++]!=':')return false;}Json v;if(!value(v,depth+1))return false;if(obj)j.object[key]=v;else{if(j.array.size()>=128)return false;j.array.push_back(v);}ws();if(p==s.size())return false;c=s[p++];if(c==(obj?'}':']'))return true;if(c!=',')return false;}while(true);}if(s.compare(p,4,"true")==0){p+=4;j.type=Json::Boolean;j.number=1;return true;}if(s.compare(p,5,"false")==0){p+=5;j.type=Json::Boolean;return true;}if(s.compare(p,4,"null")==0){p+=4;return true;}bool minus=c=='-';if(minus)p++;size_t first=p;int64_t n=0;while(p<s.size()&&s[p]>='0'&&s[p]<='9'){if(n>900719925474099LL)return false;n=n*10+s[p++]-'0';if(n>9007199254740991LL)return false;}if(p==first||(p-first>1&&s[first]=='0'))return false;j=Json::integer(minus?-n:n);return true;}
public:Parser(const std::string &v):s(v),p(0),nodes(0){}bool run(Json &j){if(!value(j,0))return false;ws();return p==s.size();}
};
bool parse(const std::string &s,Json &j,size_t limit){j=Json();if(s.empty()||s.size()>limit)return false;return Parser(s).run(j);}
static std::string quote(const std::string&s){std::string o="\"";for(size_t i=0;i<s.size();i++){unsigned char c=s[i];if(c=='"'||c=='\\'){o+='\\';o+=c;}else if(c<32){char b[7];snprintf(b,sizeof b,"\\u%04x",c);o+=b;}else o+=c;}return o+'"';}
std::string encode(const Json &j){if(j.type==Json::String)return quote(j.string);if(j.type==Json::Integer)return decimal(j.number);if(j.type==Json::Boolean)return j.number?"true":"false";if(j.type==Json::Null)return "null";std::string s=j.type==Json::Object?"{":"[";if(j.type==Json::Object){for(std::map<std::string,Json>::const_iterator i=j.object.begin();i!=j.object.end();++i){if(i!=j.object.begin())s+=',';s+=quote(i->first)+":"+encode(i->second);}}else for(size_t i=0;i<j.array.size();i++){if(i)s+=',';s+=encode(j.array[i]);}return s+(j.type==Json::Object?"}":"]");}
static const char b64[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
std::string base64(const std::string &s){std::string o;for(size_t i=0;i<s.size();i+=3){unsigned a=(unsigned char)s[i],b=i+1<s.size()?(unsigned char)s[i+1]:0,c=i+2<s.size()?(unsigned char)s[i+2]:0;o+=b64[a>>2];o+=b64[((a&3)<<4)|(b>>4)];o+=i+1<s.size()?b64[((b&15)<<2)|(c>>6)]:'=';o+=i+2<s.size()?b64[c&63]:'=';}return o;}
bool unbase64(const std::string&s,std::string &o,size_t limit){o.clear();if(s.size()%4||s.size()>4*((limit+2)/3))return false;unsigned acc=0,bits=0;bool pad=false;for(size_t i=0;i<s.size();i++){if(s[i]=='='){pad=true;continue;}const char*p=strchr(b64,s[i]);if(pad||!p||!s[i])return false;acc=(acc<<6)|(p-b64);bits+=6;if(bits>=8){bits-=8;o+=char((acc>>bits)&255);if(o.size()>limit)return false;}}return base64(o)==s;}
std::string resumeState(const std::string &s,bool newBoot,bool target){if(s=="APPLYING")return "RECOVERY_REQUIRED";if(s=="COMMITTED_PENDING_REBOOT")return newBoot&&target?"BOOT_VERIFYING":"RECOVERY_REQUIRED";if(s=="BOOT_VERIFYING")return !newBoot&&target?s:"RECOVERY_REQUIRED";if(s=="IDLE"||s=="CHECKING"||s=="OFFERED"||s=="DOWNLOADING"||s=="VERIFIED"||s=="WAITING_SAFE_WINDOW"||s=="HEALTHY"||s=="ROLLED_BACK"||s=="RECOVERY_REQUIRED")return s;return "RECOVERY_REQUIRED";}
bool confirmationGesture(const std::string &pressedAttempt,const std::string &pressedGeneration,const std::string &attempt,const std::string &generation,bool promptAtPress,bool promptNow,int dx,int dy){return pressedAttempt==attempt&&pressedGeneration==generation&&(!promptNow||promptAtPress)&&dx>-16&&dx<16&&dy>-16&&dy<16;}
bool due(int64_t now,int64_t last){return now>=946684800LL&&(last<=0||now<last||now-last>=86400);}
}
